INSERT INTO `quest_offer_reward` (`ID`,`Emote1`,`Emote2`,`Emote3`,`Emote4`,`EmoteDelay1`,`EmoteDelay2`,`EmoteDelay3`,`EmoteDelay4`,`RewardText`,`VerifiedBuild`) VALUES
(87760,0,0,0,0,0,0,0,0,'This has been a long journey, $n, but it was worth it.$B$BAt long last, you have wrested away the rod that the naga use to compel the sea creatures into their service. I will make sure it is destroyed, and the threshers and sea turtles can finally live in peace.$B$BThank you again. Your persistence has finally been rewarded, and I, personally, am grateful to you.',0);
INSERT INTO `quest_request_items` (`ID`,`EmoteOnComplete`,`EmoteOnIncomplete`,`EmoteOnCompleteDelay`,`EmoteOnIncompleteDelay`,`CompletionText`,`VerifiedBuild`) VALUES
(87760,0,0,0,0,'We will finally have resolution to this mystery, and the animals will have peace at last!',0);
