INSERT INTO `quest_offer_reward` (`ID`,`Emote1`,`Emote2`,`Emote3`,`Emote4`,`EmoteDelay1`,`EmoteDelay2`,`EmoteDelay3`,`EmoteDelay4`,`RewardText`,`VerifiedBuild`) VALUES
(98298,0,0,0,0,0,0,0,0,'It appears I get the last laugh after all, haha! Arugal truly was a fool. And I, Dalar Dawnweaver, have exposed him as the fraud he is.$B$BThese pieces are all the proof I need that the curse has nothing to do with that blithering dolt.$B$BRegrettably, that means his remedy is also worth nothing. It seems the search for a solution to the worgen curse continues.',0);
INSERT INTO `quest_request_items` (`ID`,`EmoteOnComplete`,`EmoteOnIncomplete`,`EmoteOnCompleteDelay`,`EmoteOnIncompleteDelay`,`CompletionText`,`VerifiedBuild`) VALUES
(98298,0,0,0,0,'Fangs, claws, gizzards. It makes no difference to me. The easiest way to study something is to see the guts yourself.',0);
